namespace RentCarManagement.Api.Models;
public enum VehicleStatus { Available, Rented, Maintenance, Inactive } public enum RentalStatus { Active, Returned, Cancelled } public enum DamageStatus { Reported, Paid }
public sealed class User { public int Id { get; set; } public string FullName { get; set; } = ""; public string Email { get; set; } = ""; public string PasswordHash { get; set; } = ""; public string Role { get; set; } = "Customer"; public string? PhoneNumber { get; set; } public string? DriverLicenseNumber { get; set; } public DateTime? DriverLicenseExpiry { get; set; } public List<Rental> Rentals { get; set; } = []; }
public sealed class Vehicle { public int Id { get; set; } public string Brand { get; set; } = ""; public string Model { get; set; } = ""; public int Year { get; set; } public int Mileage { get; set; } public int MaintenanceMileageThreshold { get; set; } = 10000; public VehicleStatus Status { get; set; } = VehicleStatus.Available; public decimal DailyRate { get; set; } public decimal ExtraKilometerRate { get; set; } public DateTime? LastMaintenanceDate { get; set; } public List<Rental> Rentals { get; set; } = []; }
public sealed class Rental { public int Id { get; set; } public int UserId { get; set; } public User User { get; set; } = null!; public int VehicleId { get; set; } public Vehicle Vehicle { get; set; } = null!; public DateTime StartDate { get; set; } public DateTime ExpectedReturnDate { get; set; } public DateTime? ActualReturnDate { get; set; } public int StartMileage { get; set; } public int? EndMileage { get; set; } public decimal TotalAmount { get; set; } public decimal LateFee { get; set; } public RentalStatus Status { get; set; } = RentalStatus.Active; public List<DamageReport> DamageReports { get; set; } = []; }
public sealed class DamageReport { public int Id { get; set; } public int RentalId { get; set; } public Rental Rental { get; set; } = null!; public string Description { get; set; } = ""; public decimal Amount { get; set; } public DamageStatus Status { get; set; } = DamageStatus.Reported; public DateTime ReportedAt { get; set; } = DateTime.UtcNow; public DateTime? PaidAt { get; set; } }
